/**
 * Static lint orchestration for a single QuestionSuite document.
 *
 * Order matters and is part of the contract: JSON parse, then JSON Schema,
 * then cross-reference checks. Cross-reference checks are never run over
 * input that failed schema validation, and checks that did not run are
 * reported as `not_run`, never as a pass.
 *
 * Pure: the caller supplies the source text, the capabilities profile, the
 * rule-ID catalog, and compiled validators. No filesystem or network access.
 */
import type { BackendCapabilities, CheckCoverage, Diagnostic, DiagnosticLocation, QuestionSuite } from "./contracts.js";
import type { LocationIndex } from "./locate.js";
import { buildLocationIndex, JsonScanError, positionAtOffset, tryBuildLocationIndex } from "./locate.js";
import type { SchemaValidators } from "./schema-validation.js";
import { lintValidatedSuite } from "./static-checks.js";

export const LINT_SCOPE = "static_lint_only";
export const LINT_NOTE =
  "Static lint only: semantic screening, dataset probes, metamorphic tests, fuzzing, and calibration were NOT run. A clean static lint is not semantic approval.";

export interface LintSummary {
  errors: number;
  warnings: number;
  infos: number;
  rulesChecked: number;
  rulesFlagged: number;
  rulesNotRun: number;
}

export interface LintReport {
  tool: "qlint";
  version: string;
  scope: typeof LINT_SCOPE;
  file: string | null;
  suiteId: string | null;
  schemaVersion: string | null;
  diagnostics: Diagnostic[];
  coverage: CheckCoverage[];
  notExecuted: string[];
  summary: LintSummary;
  note: string;
}

export interface LintRequest {
  source: string;
  /** Path shown in diagnostics; omit for in-memory use. */
  file?: string;
  capabilities?: BackendCapabilities;
  /** Every rule ID from rules/catalog.json, in catalog order. */
  catalogRuleIds: string[];
  validators: SchemaValidators;
  version: string;
}

/** Raised when the linter contradicts its own Diagnostic contract; a tool bug, not a user error. */
export class InternalLintError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InternalLintError";
  }
}

function syntaxLocation(error: unknown, source: string): DiagnosticLocation {
  const message = error instanceof Error ? error.message : String(error);
  const lineColumn = /\(line (\d+) column (\d+)\)/.exec(message);
  if (lineColumn) {
    return { pointer: "/", line: Number(lineColumn[1]), column: Number(lineColumn[2]) };
  }
  const position = /position (\d+)/.exec(message);
  if (position) {
    const at = positionAtOffset(source, Number(position[1]));
    return { pointer: "/", line: at.line, column: at.column };
  }
  // Some engine versions ("Unexpected end of JSON input") carry no position;
  // the scanner reports where parsing stopped.
  try {
    buildLocationIndex(source);
  } catch (error) {
    if (error instanceof JsonScanError) {
      const at = positionAtOffset(source, error.offset);
      return { pointer: "/", line: at.line, column: at.column };
    }
  }
  return { pointer: "/" };
}

function withFileLocations(diagnostic: Diagnostic, index: LocationIndex | undefined, file: string | undefined): Diagnostic {
  return {
    ...diagnostic,
    locations: diagnostic.locations.map(location => {
      const position = index?.nearest(location.pointer);
      return {
        ...location,
        ...(file === undefined ? {} : { file }),
        ...(position === undefined ? {} : { line: position.line, column: position.column }),
      };
    }),
  };
}

function schemaDiagnostic(message: string, location: DiagnosticLocation, file: string | undefined): Diagnostic {
  return {
    ruleId: "QCT001",
    severity: "error",
    basis: "static_proof",
    message,
    locations: [file === undefined ? location : { ...location, file }],
    evidence: [{ kind: "contract_ref", pointer: location.pointer }],
  };
}

function countSeverities(diagnostics: Diagnostic[]): Pick<LintSummary, "errors" | "warnings" | "infos"> {
  let errors = 0;
  let warnings = 0;
  let infos = 0;
  for (const diagnostic of diagnostics) {
    if (diagnostic.severity === "error") errors += 1;
    else if (diagnostic.severity === "warning") warnings += 1;
    else infos += 1;
  }
  return { errors, warnings, infos };
}

export function lintSuiteSource(request: LintRequest): LintReport {
  const { source, file, capabilities, catalogRuleIds, validators, version } = request;
  const index = tryBuildLocationIndex(source);
  const diagnostics: Diagnostic[] = [];
  const statuses = new Map<string, CheckCoverage["status"]>();
  let notExecuted: string[];
  let suiteId: string | null = null;
  let schemaVersion: string | null = null;

  let parsed: unknown = undefined;
  let parseError: unknown = undefined;
  try {
    parsed = JSON.parse(source);
  } catch (error) {
    parseError = error;
  }

  if (parseError !== undefined) {
    diagnostics.push(schemaDiagnostic(`Invalid JSON: ${parseError instanceof Error ? parseError.message : String(parseError)}`, syntaxLocation(parseError, source), file));
    statuses.set("QCT001", "flagged");
    notExecuted = [
      "cross-reference checks (QCT002-QCT009) and backend capability checks (QBE001-QBE002): the input is not valid JSON",
    ];
  } else {
    const issues = validators.suite(parsed);
    if (issues.length > 0) {
      for (const issue of issues) {
        diagnostics.push(withFileLocations(schemaDiagnostic(`Schema violation: ${issue.message}`, { pointer: issue.pointer }, file), index, file));
      }
      statuses.set("QCT001", "flagged");
      notExecuted = [
        "cross-reference checks (QCT002-QCT009) and backend capability checks (QBE001-QBE002): the input failed JSON Schema validation",
      ];
    } else {
      statuses.set("QCT001", "passed");
      const report = lintValidatedSuite(parsed as QuestionSuite, capabilities);
      for (const diagnostic of report.diagnostics) {
        diagnostics.push(withFileLocations(diagnostic, index, file));
      }
      for (const ruleId of report.executedRuleIds) statuses.set(ruleId, "passed");
      for (const diagnostic of report.diagnostics) statuses.set(diagnostic.ruleId, "flagged");
      notExecuted = report.notExecuted.filter(item => item !== "JSON Schema validation (caller responsibility)");
      if (capabilities === undefined) {
        notExecuted.push("backend capability checks (QBE001-QBE002; no capability profile provided)");
      }
      const parsedSuite = parsed as Partial<QuestionSuite>;
      if (typeof parsedSuite.id === "string") suiteId = parsedSuite.id;
      if (typeof parsedSuite.schemaVersion === "string") schemaVersion = parsedSuite.schemaVersion;
    }
  }

  const coverage: CheckCoverage[] = catalogRuleIds.map(ruleId => ({
    ruleId,
    status: statuses.get(ruleId) ?? "not_run",
  }));

  for (const diagnostic of diagnostics) {
    const issues = validators.diagnostic(diagnostic);
    if (issues.length > 0) {
      throw new InternalLintError(
        `emitted diagnostic ${diagnostic.ruleId} does not satisfy schemas/diagnostic.schema.json: ${issues.map(issue => issue.message).join("; ")}`,
      );
    }
  }

  return {
    tool: "qlint",
    version,
    scope: LINT_SCOPE,
    file: file ?? null,
    suiteId,
    schemaVersion,
    diagnostics,
    coverage,
    notExecuted,
    summary: {
      ...countSeverities(diagnostics),
      rulesChecked: coverage.filter(entry => entry.status === "passed" || entry.status === "flagged").length,
      rulesFlagged: coverage.filter(entry => entry.status === "flagged").length,
      rulesNotRun: coverage.filter(entry => entry.status === "not_run").length,
    },
    note: LINT_NOTE,
  };
}

state.locate_ts:
/**
 * Maps JSON Pointers to positions in the original JSON text.
 *
 * Used after JSON.parse has already accepted the document, to attach
 * 1-based line/column numbers to diagnostics. This module never decides
 * whether a document is valid, and it is pure: no filesystem, network, or
 * environment access, no mutation of its input.
 */

export interface SourcePosition {
  /** UTF-16 offset into the source text. */
  offset: number;
  /** 1-based line number. */
  line: number;
  /** 1-based column number, counted in UTF-16 code units. */
  column: number;
}

export interface LocationIndex {
  /** Position of the value at this exact pointer, when it was indexed. */
  exact(pointer: string): SourcePosition | undefined;
  /** Position of the exact pointer, or the closest indexed ancestor. */
  nearest(pointer: string): SourcePosition | undefined;
}

/** Position of a UTF-16 offset in the source; 1-based line and column. */
export function positionAtOffset(source: string, offset: number): SourcePosition {
  const clamped = Math.max(0, Math.min(offset, source.length));
  let line = 1;
  let lineStart = 0;
  for (let i = 0; i < clamped; i += 1) {
    if (source.charCodeAt(i) === 10) {
      line += 1;
      lineStart = i + 1;
    }
  }
  return { offset: clamped, line, column: clamped - lineStart + 1 };
}

export class JsonScanError extends Error {
  readonly offset: number;
  constructor(message: string, offset: number) {
    super(message);
    this.name = "JsonScanError";
    this.offset = offset;
  }
}

const WHITESPACE = new Set([" ", "\t", "\n", "\r"]);
const SCALAR = /(?:-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null)/y;

function escapeSegment(segment: string): string {
  return segment.replace(/~/g, "~0").replace(/\//g, "~1");
}

/** Reads one JSON string starting at the opening quote. */
function decodeString(source: string, start: number): { value: string; end: number } {
  let i = start + 1;
  let value = "";
  for (;;) {
    if (i >= source.length) throw new JsonScanError("Unterminated string", start);
    const ch = source[i]!;
    if (ch === '"') return { value, end: i + 1 };
    if (ch !== "\\") {
      value += ch;
      i += 1;
      continue;
    }
    i += 1;
    if (i >= source.length) throw new JsonScanError("Unterminated escape", i);
    const esc = source[i]!;
    switch (esc) {
      case '"': value += '"'; break;
      case "\\": value += "\\"; break;
      case "/": value += "/"; break;
      case "b": value += "\b"; break;
      case "f": value += "\f"; break;
      case "n": value += "\n"; break;
      case "r": value += "\r"; break;
      case "t": value += "\t"; break;
      case "u": {
        const hex = source.slice(i + 1, i + 5);
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw new JsonScanError("Invalid \\u escape", i);
        value += String.fromCharCode(Number.parseInt(hex, 16));
        i += 4;
        break;
      }
      default:
        throw new JsonScanError(`Invalid escape \\${esc}`, i);
    }
    i += 1;
  }
}

/**
 * Scans JSON text and records the first position of every value.
 * Duplicate object keys keep the first position; JSON.parse keeps the last,
 * so a duplicate-key diagnostic may point at the earlier occurrence.
 */
export function buildLocationIndex(source: string): LocationIndex {
  const lineStarts = [0];
  for (let i = 0; i < source.length; i += 1) {
    if (source.charCodeAt(i) === 10) lineStarts.push(i + 1);
  }
  const positionAt = (offset: number): SourcePosition => {
    let low = 0;
    let high = lineStarts.length - 1;
    while (low < high) {
      const mid = (low + high + 1) >> 1;
      if (lineStarts[mid]! <= offset) low = mid;
      else high = mid - 1;
    }
    return { offset, line: low + 1, column: offset - lineStarts[low]! + 1 };
  };

  const positions = new Map<string, SourcePosition>();
  const segments: string[] = [];
  let i = 0;

  // The root value is indexed under "" (JSON Pointer convention); the CLI
  // renders the root placeholder as "/" where the contract requires \S.
  const pointerOf = (): string => segments.length === 0 ? "" : "/" + segments.map(escapeSegment).join("/");
  const skipWhitespace = (): void => {
    while (i < source.length && WHITESPACE.has(source[i]!)) i += 1;
  };
  const record = (): void => {
    const pointer = pointerOf();
    if (!positions.has(pointer)) positions.set(pointer, positionAt(i));
  };

  const scalar = (): void => {
    SCALAR.lastIndex = i;
    const match = SCALAR.exec(source);
    if (!match || match.index !== i) throw new JsonScanError("Invalid JSON token", i);
    i = SCALAR.lastIndex;
  };

  const value = (): void => {
    skipWhitespace();
    record();
    const ch = source[i];
    if (ch === "{") { object(); return; }
    if (ch === "[") { array(); return; }
    if (ch === '"') { i = decodeString(source, i).end; return; }
    scalar();
  };

  const object = (): void => {
    i += 1;
    skipWhitespace();
    if (source[i] === "}") { i += 1; return; }
    for (;;) {
      skipWhitespace();
      if (source[i] !== '"') throw new JsonScanError("Expected a property name", i);
      const key = decodeString(source, i);
      i = key.end;
      skipWhitespace();
      if (source[i] !== ":") throw new JsonScanError("Expected ':'", i);
      i += 1;
      segments.push(key.value);
      value();
      segments.pop();
      skipWhitespace();
      if (source[i] === ",") { i += 1; continue; }
      if (source[i] === "}") { i += 1; return; }
      throw new JsonScanError("Expected ',' or '}'", i);
    }
  };

  const array = (): void => {
    i += 1;
    skipWhitespace();
    if (source[i] === "]") { i += 1; return; }
    let index = 0;
    for (;;) {
      segments.push(String(index));
      value();
      segments.pop();
      index += 1;
      skipWhitespace();
      if (source[i] === ",") { i += 1; continue; }
      if (source[i] === "]") { i += 1; return; }
      throw new JsonScanError("Expected ',' or ']'", i);
    }
  };

  value();
  skipWhitespace();
  if (i !== source.length) throw new JsonScanError("Unexpected content after the top-level value", i);

  const exact = (pointer: string): SourcePosition | undefined => positions.get(pointer);
  const nearest = (pointer: string): SourcePosition | undefined => {
    let candidate = pointer;
    for (;;) {
      const found = positions.get(candidate);
      if (found) return found;
      const slash = candidate.lastIndexOf("/");
      if (slash <= 0) return positions.get("");
      candidate = candidate.slice(0, slash);
    }
  };
  return { exact, nearest };
}

/** Returns undefined for text the scanner cannot index; callers keep the pointer only. */
export function tryBuildLocationIndex(source: string): LocationIndex | undefined {
  try {
    return buildLocationIndex(source);
  } catch {
    return undefined;
  }
}
